<?php
require_once dirname(__DIR__).'/includes/functions.php';require_once dirname(__DIR__).'/includes/blockchain.php';$admin=require_role('admin');$eventId=(int)($_GET['event']??0);$s=db()->prepare('SELECT * FROM events WHERE id=?');$s->execute([$eventId]);$event=$s->fetch();if(!$event){http_response_code(404);exit('Event not found.');}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$ids=array_map('intval',(array)($_POST['ids']??[]));$action=(string)($_POST['action']??'');if($ids&&in_array($action,['Verified','Rejected'],true)){db()->beginTransaction();try{$set=db()->prepare('UPDATE registrations SET status=? WHERE id=? AND event_id=?');$r=db()->prepare('SELECT user_id FROM registrations WHERE id=? AND event_id=?');foreach($ids as $id){$set->execute([$action,$id,$eventId]);$r->execute([$id,$eventId]);$uid=$r->fetchColumn();if($uid)notify_user((int)$uid,$eventId,'status','Registration '.$action,strtolower($action).' for '.$event['title'].'.');}db()->commit();flash('success',count($ids).' registration(s) marked '.$action.'.');}catch(Throwable $e){db()->rollBack();throw $e;}}elseif($action==='tamper'&&$ids){$chosen=$ids[0];db()->prepare("UPDATE registrations SET phone=IF(phone='0000000000','9999999999','0000000000') WHERE id=? AND event_id=?")->execute([$chosen,$eventId]);flash('warning','Demo tampering applied to registration #'.$chosen.'. Verify it to see detection.');}redirect('admin/participants.php?event='.$eventId.($q=trim((string)($_GET['q']??''))?'&q='.urlencode($q):''));}
$q=trim((string)($_GET['q']??''));$department=(string)($_GET['department']??'');$status=(string)($_GET['status']??'');$where=['r.event_id=?'];$params=[$eventId];if($q!==''){$where[]='(r.name LIKE ? OR r.reg_no LIKE ? OR r.email LIKE ?)';$like='%'.$q.'%';array_push($params,$like,$like,$like);}if($department!==''){$where[]='r.department=?';$params[]=$department;}if(in_array($status,['Pending','Verified','Rejected','Cancelled'],true)){$where[]='r.status=?';$params[]=$status;}$sql='SELECT r.*,u.name AS account_name,l.id AS block_id,l.block_hash FROM registrations r JOIN users u ON u.id=r.user_id LEFT JOIN blockchain_ledger l ON l.id=(SELECT MAX(l2.id) FROM blockchain_ledger l2 WHERE l2.registration_id=r.id) WHERE '.implode(' AND ',$where).' ORDER BY r.created_at DESC';$s=db()->prepare($sql);$s->execute($params);$rows=$s->fetchAll();$departments=db()->prepare('SELECT DISTINCT department FROM registrations WHERE event_id=? ORDER BY department');$departments->execute([$eventId]);$depts=$departments->fetchAll(PDO::FETCH_COLUMN);$seats=event_seats_left($eventId,(int)$event['max_participants']);$pageTitle='Event participants';require dirname(__DIR__).'/includes/header.php';
?>
<div class="d-flex flex-wrap justify-content-between align-items-end gap-3 mb-4"><div><p class="text-primary small fw-bold text-uppercase mb-1">Participants</p><h1 class="h2 fw-bold"><?=e($event['title'])?></h1><p class="mb-0 text-secondary"><?=((int)$event['max_participants']-$seats)?> / <?=e((string)$event['max_participants'])?> seats filled</p></div><a class="btn btn-outline-secondary" href="<?=e(url('admin/events.php'))?>">Back to events</a></div>
<form class="card p-3 mb-3 row flex-row g-2"><input type="hidden" name="event" value="<?=$eventId?>"><div class="col-md"><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Search name, registration ID, email"></div><div class="col-md-3"><select class="form-select" name="department"><option value="">All departments</option><?php foreach($depts as $d):?><option <?= $department===$d?'selected':''?>><?=e($d)?></option><?php endforeach;?></select></div><div class="col-md-2"><select class="form-select" name="status"><option value="">Any status</option><?php foreach(['Pending','Verified','Rejected','Cancelled'] as $st):?><option <?= $status===$st?'selected':''?>><?=e($st)?></option><?php endforeach;?></select></div><div class="col-auto"><button class="btn btn-outline-primary">Filter</button></div><div class="col-auto"><a class="btn btn-outline-success" href="<?=e(url('admin/export_participants.php?event='.$eventId))?>">Export CSV</a></div></form>
<form method="post" class="card table-responsive"><?=csrf_field()?><table class="table table-hover mb-0"><thead><tr><th><input type="checkbox" id="select-all"></th><th>Student</th><th>Contact</th><th>Registered</th><th>Status</th><th>Integrity</th></tr></thead><tbody><?php foreach($rows as $r):$check=verify_registration((int)$r['id'],false);?><tr><td><input type="checkbox" name="ids[]" value="<?=(int)$r['id']?>"></td><td><strong><?=e($r['name'])?></strong><div class="small text-secondary"><?=e($r['reg_no'])?> · <?=e($r['department'])?></div></td><td><?=e($r['email'])?><div class="small text-secondary"><?=e($r['phone'])?></div></td><td><?=e(date('M j, Y',strtotime($r['created_at'])))?></td><td><span class="badge <?= $r['status']==='Verified'?'text-bg-success':($r['status']==='Rejected'?'text-bg-danger':'text-bg-warning')?>"><?=e($r['status'])?></span></td><td><?php if($check['secure']):?><span class="badge status-secure">Secure #<?=e((string)$check['block']['id'])?></span><?php else:?><a class="badge text-bg-danger" href="<?=e(url('admin/verify.php?id='.(int)$r['id']))?>">Tampered</a><?php endif;?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6" class="empty-state">No registrations found.</td></tr><?php endif;?></tbody></table><div class="p-3 d-flex gap-2 flex-wrap"><button class="btn btn-sm btn-success" name="action" value="Verified">Mark selected verified</button><button class="btn btn-sm btn-outline-danger" name="action" value="Rejected">Reject selected</button><button class="btn btn-sm btn-warning" name="action" value="tamper" data-confirm="DEMO ONLY: alter one registration without updating the ledger?">Simulate tampering (demo)</button></div></form>
<script>document.getElementById('select-all')?.addEventListener('change',e=>document.querySelectorAll('input[name="ids[]"]').forEach(c=>c.checked=e.target.checked));</script>
